package com.shootingstarscommands;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(ShootingStarsConfig.GROUP)
public interface ShootingStarsConfig extends Config
{
	String GROUP = "shooting-stars-commands";

	@ConfigSection(
		name = "Star Miners feed",
		description = "Settings for the optional third-party Shooting Stars feed.",
		position = 0
	)
	String feedSection = "feedSection";

	@ConfigItem(
		keyName = "useStarMinersFeed",
		name = "Use Star Miners feed",
		description = "Retrieve active stars from the Star Miners crowdsourcing service.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 1,
		section = feedSection
	)
	default boolean useStarMinersFeed()
	{
		return false;
	}

	@ConfigItem(
		keyName = "authorizationKey",
		name = "Star Miners authorization key",
		description = "The Authorization header value supplied by Star Miners. No key is bundled with the plugin.",
		secret = true,
		position = 2,
		section = feedSection
	)
	default String authorizationKey()
	{
		return "";
	}

}

package com.shootingstarscommands;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JLabel;
import javax.swing.JTextArea;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

final class ShootingStarsGuidePanel extends PluginPanel
{
	ShootingStarsGuidePanel()
	{
		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(8, 8, 8, 8));

		JLabel title = new JLabel("Shooting Stars Commands");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		add(title, BorderLayout.NORTH);

		JTextArea guide = new JTextArea(
			"Type these commands in game chat:\n\n"
				+ "!stars\n"
				+ "Shows all active stars. The top five fit in one chat message.\n\n"
				+ "!stars t7\n"
				+ "Shows only tier 7 stars. Use t1 through t9.\n\n"
				+ "!stars t7+\n"
				+ "Shows tier 7 and higher.\n\n"
				+ "!stars varrock\n"
				+ "Matches a reported location, without regard to letter case.\n\n"
				+ "!stars t7 varrock\n"
				+ "Combines an exact tier and a location.\n\n"
				+ "!stars help\n"
				+ "Shows this compact guide in chat.");
		guide.setEditable(false);
		guide.setFocusable(false);
		guide.setLineWrap(true);
		guide.setWrapStyleWord(true);
		guide.setFont(FontManager.getRunescapeSmallFont());
		guide.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		guide.setBackground(ColorScheme.DARK_GRAY_COLOR);
		guide.setBorder(new EmptyBorder(6, 6, 6, 6));
		add(guide, BorderLayout.CENTER);
	}

	static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setColor(ColorScheme.BRAND_ORANGE);
			graphics.fill(starPath());
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static Path2D starPath()
	{
		Path2D star = new Path2D.Double();
		int center = 8;
		double outerRadius = 7;
		double innerRadius = 3;
		for (int point = 0; point < 10; point++)
		{
			double angle = -Math.PI / 2 + point * Math.PI / 5;
			double radius = point % 2 == 0 ? outerRadius : innerRadius;
			double x = center + Math.cos(angle) * radius;
			double y = center + Math.sin(angle) * radius;
			if (point == 0)
			{
				star.moveTo(x, y);
			}
			else
			{
				star.lineTo(x, y);
			}
		}
		star.closePath();
		return star;
	}
}

package com.shootingstarscommands;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatCommandManager;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Shooting Stars Commands",
	description = "Adds a !stars chat command for active Shooting Stars",
	tags = {"shooting", "stars", "star", "mining", "chat"},
	internalName = ShootingStarsConfig.GROUP
)
public class ShootingStarsPlugin extends Plugin
{
	private static final String STARS_COMMAND = "!stars";
	private static final int MAX_STARS_IN_RESPONSE = 5;
	private static final int MAX_RESPONSE_LENGTH = 240;
	private static final int MAX_LOCATION_LENGTH = 40;
	private static final String HELP_MESSAGE = "Usage: !stars | !stars t7 | !stars t7+ | !stars varrock | !stars t7 varrock";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatCommandManager chatCommandManager;

	@Inject
	private ShootingStarsConfig config;

	@Inject
	private StarService starService;

	@Inject
	private ClientToolbar clientToolbar;

	private volatile boolean running;
	private ShootingStarsGuidePanel guidePanel;
	private NavigationButton guideNavigation;

	@Override
	protected void startUp()
	{
		running = true;
		chatCommandManager.registerCommandAsync(STARS_COMMAND, this::showStars);
		guidePanel = new ShootingStarsGuidePanel();
		guideNavigation = NavigationButton.builder()
			.tooltip("Shooting Stars Commands")
			.icon(ShootingStarsGuidePanel.createIcon())
			.priority(7)
			.panel(guidePanel)
			.build();
		clientToolbar.addNavigation(guideNavigation);
		log.debug("Shooting Stars Commands started");
	}

	@Override
	protected void shutDown()
	{
		running = false;
		chatCommandManager.unregisterCommand(STARS_COMMAND);
		starService.cancelPendingRequest();
		clientToolbar.removeNavigation(guideNavigation);
		guideNavigation = null;
		guidePanel = null;
		log.debug("Shooting Stars Commands stopped");
	}

	@Provides
	ShootingStarsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ShootingStarsConfig.class);
	}

	private void showStars(ChatMessage chatMessage, String commandText)
	{
		if (isHelpCommand(commandText))
		{
			setResponse(chatMessage, HELP_MESSAGE);
			return;
		}

		StarFilter filter = StarFilter.fromCommand(commandText);
		if (!config.useStarMinersFeed())
		{
			setResponse(chatMessage, "Enable Use Star Miners feed in the plugin settings to retrieve live stars.");
			return;
		}

		if (config.authorizationKey() == null || config.authorizationKey().trim().isEmpty())
		{
			setResponse(chatMessage, "Set your Star Miners authorization key in the plugin settings.");
			return;
		}

		starService.fetchActiveStars(new StarService.ResultCallback()
		{
			@Override
			public void onSuccess(List<Star> stars, boolean fromCache)
			{
				if (running)
				{
					setResponse(chatMessage, formatStars(filter.apply(stars), filter));
				}
			}

			@Override
			public void onFailure(String message)
			{
				if (running)
				{
					setResponse(chatMessage, message);
				}
			}
		});
	}

	private void setResponse(ChatMessage chatMessage, String response)
	{
		clientThread.invoke(() ->
		{
			if (!running)
			{
				return;
			}

			String[] lines = response.split("\\n");
			ChatMessageBuilder responseBuilder = new ChatMessageBuilder();
			appendHeader(responseBuilder, lines[0]);

			for (int index = 1; index < lines.length; index++)
			{
				responseBuilder.append("\n");
				appendStarLine(responseBuilder, lines[index]);
			}

			String formattedResponse = responseBuilder.build().replace("\n", "<br>");
			MessageNode messageNode = chatMessage.getMessageNode();
			messageNode.setRuneLiteFormatMessage(formattedResponse);
			client.refreshChat();
		});
	}

	private static void appendHeader(ChatMessageBuilder builder, String header)
	{
		int openingBracket = header.indexOf('[');
		int closingBracket = header.indexOf(']');

		if (openingBracket == -1 || closingBracket <= openingBracket)
		{
			builder.append(Color.RED, header);
			return;
		}

		builder.append(Color.RED, header.substring(0, openingBracket + 1));
		builder.append(Color.BLACK, header.substring(openingBracket + 1, closingBracket));
		builder.append(Color.RED, header.substring(closingBracket));
	}

	private static void appendStarLine(ChatMessageBuilder builder, String line)
	{
		int separator = line.indexOf(" - ");

		if (separator == -1)
		{
			builder.append(Color.RED, line);
			return;
		}

		builder.append(Color.BLACK, line.substring(0, separator + 3));
		builder.append(Color.RED, line.substring(separator + 3));
	}

	static String formatStars(List<Star> stars)
	{
		return formatStars(stars, StarFilter.fromCommand("!stars"));
	}

	static String formatStars(List<Star> stars, StarFilter filter)
	{
		if (stars.isEmpty())
		{
			return filter.isAll()
				? "No active stars were found."
				: "No active stars matched " + filter.description() + ".";
		}

		StringBuilder response = new StringBuilder(filter.isAll() ? "Stars:" : "Stars [" + filter.description() + "]:");
		int starsShown = 0;
		for (Star star : stars)
		{
			if (starsShown == MAX_STARS_IN_RESPONSE)
			{
				break;
			}

			String entry = "W" + star.getWorld() + " T" + star.getTier();
			if (!star.getLocation().isEmpty())
			{
				entry += " - " + abbreviateLocation(star.getLocation());
			}

			if (response.length() + 1 + entry.length() > MAX_RESPONSE_LENGTH)
			{
				break;
			}

			response.append('\n').append(entry);
			starsShown++;
		}

		if (starsShown == 0)
		{
			return "Active stars were found, but their details were too long to display.";
		}
		if (starsShown < stars.size())
		{
			String remaining = "+" + (stars.size() - starsShown) + " more";
			if (response.length() + 1 + remaining.length() <= MAX_RESPONSE_LENGTH)
			{
				response.append('\n').append(remaining);
			}
		}
		return response.toString();
	}

	static boolean isHelpCommand(String commandText)
	{
		return "!stars help".equalsIgnoreCase(commandText)
			|| "!stars commands".equalsIgnoreCase(commandText);
	}

	private static String abbreviateLocation(String location)
	{
		if (location.length() <= MAX_LOCATION_LENGTH)
		{
			return location;
		}
		return location.substring(0, MAX_LOCATION_LENGTH - 1) + "…";
	}

}

package com.shootingstarscommands;

import java.util.Objects;

public final class Star
{
	private final int world;
	private final int tier;
	private final String location;
	private final long lastUpdated;

	public Star(int world, int tier, String location, long lastUpdated)
	{
		this.world = world;
		this.tier = tier;
		this.location = Objects.requireNonNull(location);
		this.lastUpdated = lastUpdated;
	}

	public int getWorld()
	{
		return world;
	}

	public int getTier()
	{
		return tier;
	}

	public String getLocation()
	{
		return location;
	}

	public long getLastUpdated()
	{
		return lastUpdated;
	}
}

package com.shootingstarscommands;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

final class StarFilter
{
	private static final Pattern TIER_FILTER = Pattern.compile("(?i)^t?([1-9])(\\+)?(?:\\s+(.+))?$");
	private static final StarFilter ALL = new StarFilter(0, false, "");

	private final int tier;
	private final boolean minimumTier;
	private final String locationQuery;

	private StarFilter(int tier, boolean minimumTier, String locationQuery)
	{
		this.tier = tier;
		this.minimumTier = minimumTier;
		this.locationQuery = locationQuery;
	}

	static StarFilter fromCommand(String commandText)
	{
		if (commandText == null)
		{
			return ALL;
		}

		String plainText = Text.removeTags(commandText).trim();
		if (!plainText.regionMatches(true, 0, "!stars", 0, "!stars".length()))
		{
			return ALL;
		}

		String filterText = plainText.substring("!stars".length()).trim();
		if (filterText.isEmpty() || filterText.equalsIgnoreCase("all"))
		{
			return ALL;
		}

		Matcher tierMatcher = TIER_FILTER.matcher(filterText);
		if (tierMatcher.matches())
		{
			String location = normalizeLocation(tierMatcher.group(3));
			return new StarFilter(Integer.parseInt(tierMatcher.group(1)), tierMatcher.group(2) != null, location);
		}

		return new StarFilter(0, false, normalizeLocation(filterText));
	}

	List<Star> apply(List<Star> stars)
	{
		List<Star> matchingStars = new ArrayList<>();
		for (Star star : stars)
		{
			if (matches(star))
			{
				matchingStars.add(star);
			}
		}
		return matchingStars;
	}

	String description()
	{
		String tierDescription = tier == 0 ? "" : "T" + tier + (minimumTier ? "+" : "");
		if (locationQuery.isEmpty())
		{
			return tierDescription;
		}
		if (tierDescription.isEmpty())
		{
			return displayLocation();
		}
		return tierDescription + ", " + displayLocation();
	}

	boolean isAll()
	{
		return tier == 0 && locationQuery.isEmpty();
	}

	private boolean matches(Star star)
	{
		if (tier != 0 && (minimumTier ? star.getTier() < tier : star.getTier() != tier))
		{
			return false;
		}
		return locationQuery.isEmpty()
			|| star.getLocation().toLowerCase(Locale.ROOT).contains(locationQuery.toLowerCase(Locale.ROOT));
	}

	private static String normalizeLocation(String location)
	{
		return location == null ? "" : location.trim().replaceAll("\\s+", " ");
	}

	private String displayLocation()
	{
		return locationQuery.substring(0, 1).toUpperCase(Locale.ROOT) + locationQuery.substring(1);
	}
}

package com.shootingstarscommands;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Text;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;

@Slf4j
@Singleton
public class StarService
{
	static final String STAR_MINERS_ENDPOINT = "https://public.starminers.site/crowdsource";
	private static final String PLUGIN_NAME = "Shooting Stars Commands";
	static final long CACHE_DURATION_MILLIS = 45_000L;
	static final long REQUEST_COOLDOWN_MILLIS = 45_000L;
	static final long MAX_RESPONSE_SIZE_BYTES = 64L * 1024L;
	private static final long MAX_REPORT_AGE_SECONDS = 90L * 60L;
	private static final long MAX_FUTURE_REPORT_SECONDS = 5L * 60L;

	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final ShootingStarsConfig config;
	private final Object requestLock = new Object();
	private final List<ResultCallback> pendingCallbacks = new ArrayList<>();

	private List<Star> cachedStars = Collections.emptyList();
	private long cachedAtMillis;
	private long lastRequestAtMillis;
	private Call activeCall;

	@Inject
	StarService(OkHttpClient okHttpClient, Gson gson, ShootingStarsConfig config)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.config = config;
	}

	/**
	 * Gets active stars from the short-lived cache or queues one non-blocking HTTP request.
	 * Every callback is called from the caller thread for cached data, or an OkHttp thread for
	 * fresh data. Callers that touch RuneLite state must move that work to the client thread.
	 */
	public void fetchActiveStars(ResultCallback callback)
	{
		List<Star> cacheHit = null;
		List<ResultCallback> requestCreationFailureCallbacks = null;
		Call callToEnqueue = null;
		boolean requestIsCoolingDown = false;
		synchronized (requestLock)
		{
			long nowMillis = System.currentTimeMillis();
			if (cachedAtMillis > 0 && nowMillis - cachedAtMillis < CACHE_DURATION_MILLIS)
			{
				cacheHit = cachedStars;
			}
			else if (activeCall != null)
			{
				pendingCallbacks.add(callback);
				return;
			}
			else if (isRequestCooldownActive(lastRequestAtMillis, nowMillis))
			{
				requestIsCoolingDown = true;
			}
			else
			{
				pendingCallbacks.add(callback);
				lastRequestAtMillis = nowMillis;
				try
				{
					Request.Builder builder = new Request.Builder()
						.url(STAR_MINERS_ENDPOINT)
						.cacheControl(CacheControl.FORCE_NETWORK)
						.header("Plugin", PLUGIN_NAME);
					String authorizationKey = config.authorizationKey();
					if (authorizationKey != null && !authorizationKey.trim().isEmpty())
					{
						builder.header("Authorization", authorizationKey.trim());
					}
					callToEnqueue = okHttpClient.newCall(builder.build());
					activeCall = callToEnqueue;
				}
				catch (IllegalArgumentException e)
				{
					log.debug("Could not create Star Miners request", e);
					requestCreationFailureCallbacks = takePendingCallbacks();
				}
			}
		}

		if (cacheHit != null)
		{
			callback.onSuccess(cacheHit, true);
			return;
		}
		if (requestIsCoolingDown)
		{
			callback.onFailure("Shooting Stars were recently unavailable. Try again shortly.");
			return;
		}
		if (requestCreationFailureCallbacks != null)
		{
			notifyFailure(requestCreationFailureCallbacks, "Unable to retrieve Shooting Stars right now.");
			return;
		}

		if (callToEnqueue == null)
		{
			return;
		}

		callToEnqueue.enqueue(new okhttp3.Callback()
		{
			@Override
			public void onFailure(Call failedCall, IOException e)
			{
				log.debug("Star Miners request failed", e);
				completeFailure(failedCall, "Unable to retrieve Shooting Stars right now.");
			}

			@Override
			public void onResponse(Call responseCall, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						log.debug("Star Miners request returned HTTP {}", response.code());
						completeFailure(responseCall, response.code() == 401 || response.code() == 403
							? "Star Miners rejected the authorization key."
							: "Unable to retrieve Shooting Stars right now.");
						return;
					}

					List<Star> stars = parseStars(gson, readResponseBody(body), Instant.now().getEpochSecond());
					completeSuccess(responseCall, stars);
				}
				catch (IOException | JsonParseException | IllegalStateException e)
				{
					log.debug("Could not read Star Miners response", e);
					completeFailure(responseCall, "Unable to retrieve Shooting Stars right now.");
				}
			}
		});
	}

	static boolean isRequestCooldownActive(long lastRequestMillis, long nowMillis)
	{
		return lastRequestMillis > 0 && nowMillis - lastRequestMillis < REQUEST_COOLDOWN_MILLIS;
	}

	static String readResponseBody(ResponseBody body) throws IOException
	{
		long contentLength = body.contentLength();
		if (contentLength > MAX_RESPONSE_SIZE_BYTES)
		{
			throw new IOException("Star Miners response exceeded the size limit");
		}

		BufferedSource source = body.source();
		if (source.request(MAX_RESPONSE_SIZE_BYTES + 1))
		{
			throw new IOException("Star Miners response exceeded the size limit");
		}
		return source.readString(StandardCharsets.UTF_8);
	}

	public void cancelPendingRequest()
	{
		Call callToCancel;
		synchronized (requestLock)
		{
			callToCancel = activeCall;
			activeCall = null;
			pendingCallbacks.clear();
		}
		if (callToCancel != null)
		{
			callToCancel.cancel();
		}
	}

	static List<Star> parseStars(Gson gson, String responseBody, long nowEpochSeconds)
	{
		JsonElement root = gson.fromJson(responseBody, JsonElement.class);
		if (root == null || !root.isJsonArray())
		{
			throw new JsonParseException("Star Miners response was not a JSON array");
		}

		Map<Integer, Star> newestStarByWorld = new HashMap<>();
		JsonArray stars = root.getAsJsonArray();
		for (JsonElement element : stars)
		{
			if (element == null || !element.isJsonObject())
			{
				continue;
			}

			Star star = parseStar(element.getAsJsonObject(), nowEpochSeconds);
			if (star == null)
			{
				continue;
			}

			Star existing = newestStarByWorld.get(star.getWorld());
			if (existing == null || existing.getLastUpdated() < star.getLastUpdated())
			{
				newestStarByWorld.put(star.getWorld(), star);
			}
		}

		List<Star> parsedStars = new ArrayList<>(newestStarByWorld.values());
		parsedStars.sort(Comparator.comparingInt(Star::getTier).reversed()
			.thenComparingInt(Star::getWorld));
		return parsedStars;
	}

	private static Star parseStar(JsonObject entry, long nowEpochSeconds)
	{
		try
		{
			if (!hasValue(entry, "world") || !hasValue(entry, "tier") || !hasValue(entry, "calledAt"))
			{
				return null;
			}

			int world = entry.get("world").getAsInt();
			int tier = entry.get("tier").getAsInt();
			long lastUpdated = (long) entry.get("calledAt").getAsDouble();
			if (world <= 0 || tier < 1 || tier > 9 || lastUpdated <= 0
				|| lastUpdated > nowEpochSeconds + MAX_FUTURE_REPORT_SECONDS
				|| nowEpochSeconds - lastUpdated > MAX_REPORT_AGE_SECONDS)
			{
				return null;
			}

			return new Star(world, tier, location(entry), lastUpdated);
		}
		catch (NumberFormatException | UnsupportedOperationException | IllegalStateException e)
		{
			return null;
		}
	}

	private static boolean hasValue(JsonObject object, String key)
	{
		return object.has(key) && !object.get(key).isJsonNull();
	}

	private static String location(JsonObject entry)
	{
		if (!hasValue(entry, "calledLocation"))
		{
			return "";
		}

		String rawLocation = entry.get("calledLocation").getAsString();
		return Text.removeTags(rawLocation).replaceAll("[\\r\\n\\t]+", " ").trim();
	}

	private void completeSuccess(Call completedCall, List<Star> stars)
	{
		List<ResultCallback> callbacks;
		List<Star> immutableStars = Collections.unmodifiableList(new ArrayList<>(stars));
		synchronized (requestLock)
		{
			if (activeCall != completedCall)
			{
				return;
			}
			activeCall = null;
			cachedStars = immutableStars;
			cachedAtMillis = System.currentTimeMillis();
			callbacks = takePendingCallbacks();
		}
		for (ResultCallback callback : callbacks)
		{
			callback.onSuccess(immutableStars, false);
		}
	}

	private void completeFailure(Call completedCall, String message)
	{
		List<ResultCallback> callbacks;
		synchronized (requestLock)
		{
			if (completedCall != null && activeCall != completedCall)
			{
				return;
			}
			activeCall = null;
			callbacks = takePendingCallbacks();
		}
		notifyFailure(callbacks, message);
	}

	private static void notifyFailure(List<ResultCallback> callbacks, String message)
	{
		for (ResultCallback callback : callbacks)
		{
			callback.onFailure(message);
		}
	}

	private List<ResultCallback> takePendingCallbacks()
	{
		List<ResultCallback> callbacks = new ArrayList<>(pendingCallbacks);
		pendingCallbacks.clear();
		return callbacks;
	}

	public interface ResultCallback
	{
		void onSuccess(List<Star> stars, boolean fromCache);

		void onFailure(String message);
	}
}

